function qtyOf(item){ return DEFAULT_QTY[item] || ''; }

// Ingredients may be a plain string ("עגבניות") or {name, qty} for recipe-specific amounts.
function ingName(i){
  if(i == null) return '';
  if(typeof i === 'string') return i;
  return i.name || i.item || '';
}
function ingQty(i){
  if(i && typeof i === 'object' && i.qty) return i.qty;
  return qtyOf(ingName(i));
}
function recipeIngNames(r){ return (r.ingredients || []).map(ingName); }
// Parse a free-text ingredient line into {name, qty?} — supports "עגבניות — 3 יחידות", "3 יחידות עגבניות", or plain names.
function parseIngredientLine(line){
  line = norm(line || '');
  if(!line) return null;
  // "name — qty" / "name - qty" / "name: qty"
  let m = line.match(/^(.+?)\s*[—\-–:]\s*(.+)$/);
  if(m && m[1].length > 1){
    const left = norm(m[1]), right = norm(m[2]);
    // if left looks like a quantity, swap
    if(/^\d/.test(left) && !/^\d/.test(right)) return { name: right, qty: left };
    return { name: left, qty: right };
  }
  // leading quantity: "3 יחידות עגבניות" / "כף שמן זית"
  m = line.match(/^(\d+[\d\.\/]*\s*(?:יחידות?|כוסות?|כפות?|כפיות?|גרם|ק[״"]?ג|מ[״"]?ל|שיניים?|חופן)?)\s+(.+)$/i);
  if(m && m[2].length > 1) return { name: norm(m[2]), qty: norm(m[1]) };
  return { name: line };
}

let categoryOverrides = JSON.parse(localStorage.getItem('category_overrides')||'{}');
function catOf(item){ return categoryOverrides[item] || ING_TO_CAT[item] || 'אחר'; }
function setCategoryOverride(item, cat){
  if(cat) categoryOverrides[item] = cat; else delete categoryOverrides[item];
  localStorage.setItem('category_overrides', JSON.stringify(categoryOverrides));
  scheduleCategorySettingsPush();
}

const CATEGORY_ICONS = {"ירקות":"🥕","חלבונים":"🍗","מוצרי חלב":"🥛","פחמימות":"🍞","מזווה":"🫙","פירות":"🍎","תיבול ואפייה":"🧂","קפואים":"🧊","טואלטיקה":"🧴","חטיפים ופיצוחים":"🍿","אחר":"🛒"};
let categoryIcons = JSON.parse(localStorage.getItem('category_icons')||'{}');
function categoryIconOf(c){ return categoryIcons[c] || CATEGORY_ICONS[c] || '🏷️'; }
function setCategoryIcon(c, icon){
  if(icon) categoryIcons[c] = icon; else delete categoryIcons[c];
  localStorage.setItem('category_icons', JSON.stringify(categoryIcons));
  scheduleCategorySettingsPush();
}
let customCategories = JSON.parse(localStorage.getItem('custom_categories')||'[]');
function allCategoryNames(){ return [...new Set(Object.keys(CATALOG).concat(customCategories))]; }
// Self-healing: if a category the user once added by hand later gets baked into the permanent
// CATALOG (as happens when Claude folds a user's export into the built-in code), it would
// otherwise linger in customCategories as a redundant duplicate — making that category's items
// render twice everywhere. This drops any customCategories entry that CATALOG now already covers.
function pruneCustomCategoriesAgainstCatalog(){
  const before = customCategories.length;
  customCategories = customCategories.filter(c=>!CATALOG[c]);
  const changed = customCategories.length !== before;
  if(changed) localStorage.setItem('custom_categories', JSON.stringify(customCategories));
  return changed;
}
pruneCustomCategoriesAgainstCatalog();
function addCustomCategory(name){
  name = norm(name);
  if(!name || allCategoryNames().includes(name) || name === 'אחר') return false;
  customCategories.push(name);
  localStorage.setItem('custom_categories', JSON.stringify(customCategories));
  scheduleCategorySettingsPush();
  return true;
}
function deleteCustomCategory(name){
  customCategories = customCategories.filter(c=>c!==name);
  localStorage.setItem('custom_categories', JSON.stringify(customCategories));
  if(categoryIcons[name]){ delete categoryIcons[name]; localStorage.setItem('category_icons', JSON.stringify(categoryIcons)); }
  // items that were classified under the deleted category fall back to their default category
  Object.keys(categoryOverrides).forEach(item=>{
    if(categoryOverrides[item] === name) delete categoryOverrides[item];
  });
  localStorage.setItem('category_overrides', JSON.stringify(categoryOverrides));
  protectedCategories = protectedCategories.filter(c=>c!==name);
  localStorage.setItem('protected_categories', JSON.stringify(protectedCategories));
  scheduleCategorySettingsPush();
  scheduleAppStatePush();
}
let iconOverrides = JSON.parse(localStorage.getItem('icon_overrides')||'{}');
function iconOf(item){ return iconOverrides[item] || ING_EMOJI[item] || '🛒'; }
function setIconOverride(item, icon){
  if(icon) iconOverrides[item] = icon; else delete iconOverrides[item];
  localStorage.setItem('icon_overrides', JSON.stringify(iconOverrides));
  scheduleCategorySettingsPush();
}

let autoResetEnabled = localStorage.getItem('auto_reset_enabled') === '1';
let protectedCategories = JSON.parse(localStorage.getItem('protected_categories')||'["מזווה","תיבול ואפייה"]');
function checkDailyFridgeReset(){
  if(!autoResetEnabled) return;
  const today = new Date().toDateString();
  const last = localStorage.getItem('last_fridge_reset');
  if(last === today) return;
  [...fridge].forEach(item=>{ if(!protectedCategories.includes(catOf(item))) fridge.delete(item); });
  saveFridge();
  localStorage.setItem('last_fridge_reset', today);
}

